CREATE TABLE public.staff_branch_assignments (user_id uuid NOT NULL, branch_name text NOT NULL CHECK (length(trim(branch_name)) > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, branch_name));
GRANT SELECT, INSERT, DELETE ON public.staff_branch_assignments TO authenticated;
GRANT ALL ON public.staff_branch_assignments TO service_role;
ALTER TABLE public.staff_branch_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff view own assignments and admins view permitted assignments" ON public.staff_branch_assignments FOR SELECT TO authenticated USING (user_id = auth.uid() OR (public.is_staff_admin(auth.uid()) AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.role = 'super_admin') OR branch_name = (SELECT branch FROM public.profiles WHERE id = auth.uid()))));
CREATE POLICY "Admins add branch assignments" ON public.staff_branch_assignments FOR INSERT TO authenticated WITH CHECK (public.is_staff_admin(auth.uid()) AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = user_id AND p.is_active) AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.role = 'super_admin') OR (branch_name = (SELECT branch FROM public.profiles WHERE id = auth.uid()) AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = staff_branch_assignments.user_id AND r.role = 'super_admin'))));
CREATE POLICY "Admins remove branch assignments" ON public.staff_branch_assignments FOR DELETE TO authenticated USING (public.is_staff_admin(auth.uid()) AND user_id <> auth.uid() AND (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.role = 'super_admin') OR (branch_name = (SELECT branch FROM public.profiles WHERE id = auth.uid()) AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = staff_branch_assignments.user_id AND r.role = 'super_admin'))) AND (SELECT count(*) FROM public.staff_branch_assignments a WHERE a.user_id = staff_branch_assignments.user_id) > 1);
CREATE TRIGGER touch_staff_branch_assignments BEFORE UPDATE ON public.staff_branch_assignments FOR EACH ROW EXECUTE FUNCTION public.staff_touch_updated_at();
INSERT INTO public.staff_branch_assignments(user_id,branch_name) SELECT id,branch FROM public.profiles WHERE is_active ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.staff_sync_branch_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.is_active AND (TG_OP = 'INSERT' OR OLD.branch IS DISTINCT FROM NEW.branch) THEN INSERT INTO public.staff_branch_assignments(user_id,branch_name) VALUES (NEW.id,NEW.branch) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER sync_staff_branch_assignment AFTER INSERT OR UPDATE OF branch ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.staff_sync_branch_assignment();
REVOKE EXECUTE ON FUNCTION public.staff_sync_branch_assignment() FROM PUBLIC, anon, authenticated;